                + " AND (set_on IS NULL OR set_on <= ?) ORDER BY seq", (RowCallbackHandler) rs -> holds.add(
                        new Person.Hold(rs.getDate(1).toLocalDate(), local(rs.getDate(2)))), sheetId, now.getId(), end);
