                claim.setCorrectedDate(claims.correctedDate(sheetId, person.getId(), claim.getCorrects()));
                own.add(0, claim);
            }
        }
        return own;
    }

    private static LocalDate local(Date date) {
        return date == null ? null : date.toLocalDate();
    }
}

