import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { sheetTodayKey, useSheetArchived, useSheetToday, type SheetToday as SheetTodayDto } from './useSheetToday';

// Shows the active sheet's today and changes it. A blank date resets it to the real date.
// Also shows whether the sheet is archived, and archives it (a steward only).
export function SheetToday() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const today = useSheetToday(sheet);
  const archived = useSheetArchived(sheet);
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (value: string) =>
      postJson<SheetTodayDto>(`/api/sheets/${encodeURIComponent(sheet)}/today`, { today: value, user }),
    onSuccess: (saved) => {
      queryClient.setQueryData(sheetTodayKey(saved.sheet), saved);
      // Everything on the sheet may depend on its date: re-read it all.
      void queryClient.invalidateQueries({ queryKey: ['sheet', saved.sheet] });
    },
  });
  const archive = useMutation({
    mutationFn: () =>
      postJson<SheetTodayDto>(`/api/sheets/${encodeURIComponent(sheet)}/archive`, { user }),
    onSuccess: (saved) => {
      queryClient.setQueryData(sheetTodayKey(saved.sheet), saved);
    },
  });
  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        archive.reset();
        submitOnce(() => save.mutateAsync(date.trim()));
      }}
    >
      Today: <span data-testid="sheet-today">{today ?? ''}</span>{' '}
      <input
        type="date"
        data-testid="sheet-today-input"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          save.reset();
          archive.reset();
        }}
      />
      <button type="submit" data-testid="sheet-today-save">Set today</button>
      {' '}Archived: <span data-testid="sheet-archived">{archived === undefined ? '' : archived ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        onClick={() => {
          save.reset();
          archive.reset();
          submitOnce(() => archive.mutateAsync());
        }}
      >
        Archive sheet
      </button>
      {save.isError && <span data-testid="sheet-error" role="alert"> Could not change today.</span>}
      {archive.isError && <span data-testid="sheet-error" role="alert"> Could not archive the sheet.</span>}
    </form>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type SheetToday = { sheet: string; today: string; archived: boolean };

export const sheetTodayKey = (sheet: string) => ['sheet', sheet, 'today'] as const;

/** The sheet's today (YYYY-MM-DD). Every date decision and default date on screen reads this —
 *  never `new Date()`. Undefined while loading. */
export function useSheetToday(sheet: string): string | undefined {
  const { data } = useQuery({
    queryKey: sheetTodayKey(sheet),
    queryFn: () => getJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheet)}/today`),
    enabled: sheet !== '',
  });
  return data?.today;
}

/** Whether the sheet is archived (everything visible, every change refused). Undefined while loading. */
export function useSheetArchived(sheet: string): boolean | undefined {
  const { data } = useQuery({
    queryKey: sheetTodayKey(sheet),
    queryFn: () => getJson<SheetToday>(`/api/sheets/${encodeURIComponent(sheet)}/today`),
    enabled: sheet !== '',
  });
  return data?.archived;
}
import { asString, useSearchParam } from '../../url/useSearchParam';
import { STATUSES, useSheetFigures } from '../people/useSheetFigures';

// The sheet's counters, always on show: its people (retired included), its claims per status (as
// the summary counts them) and its due-total and overdue-total (as the sheet's totals show them).
export function SheetHeader() {
  const [sheet] = useSearchParam('sheet', asString);
  const { people, sheetDueTotal, sheetOverdueTotal, statusCount } = useSheetFigures(sheet);
  return (
    <header data-testid="header">
      People: <span data-testid="header-people-count">{people.length}</span>
      {STATUSES.map((s) => (
        <span key={s}>
          {' · '}
          {s}: <span data-testid={`header-claims-${s}-count`}>{statusCount(s)}</span>
        </span>
      ))}
      {' · '}Due: <span data-testid="header-due-total">{sheetDueTotal}</span>
      {' · '}Overdue: <span data-testid="header-overdue-total">{sheetOverdueTotal}</span>
    </header>
  );
}
import { useState } from 'react';
import { asString, useSearchParam } from '../../url/useSearchParam';

// Chooses the active sheet by id; the active id lives in the URL (`sheet`). Everything else in the
// app is kept per sheet and reads this key. A never-used id is simply an empty sheet.
export function SheetPicker() {
  const [sheet, setSheet] = useSearchParam('sheet', asString);
  const [id, setId] = useState('');
  return (
    <form
      data-testid="sheet-form"
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = id.trim();
        if (trimmed !== '') setSheet(trimmed);
      }}
    >
      <input data-testid="sheet-id-input" value={id} onChange={(e) => setId(e.target.value)} placeholder="Sheet id" />
      <button type="submit" data-testid="sheet-load">Load</button>{' '}
      Sheet: <span data-testid="sheet-current-id">{sheet}</span>
    </form>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** `version` goes up on every save; an editor sends back the version it loaded, so a save over
 *  someone else's newer one is refused. `statementCount` is how many statements were taken;
 *  `statedTotal` is the last one's due-total ("n/a" possible, "" when none) and `statementDate` the
 *  sheet's today when it was taken ("" when none). `retired` is whether a retirement date is set
 *  (retired at once, whatever the date) and `retiredFrom` is that date ("" when none). `held` is
 *  whether the person has any hold and `holds` lists each (from, to; to "" when open-ended): their
 *  OPEN claims dated within one, unless bound by a statement, count in no live total. `patrons` are the
 *  names of the people they named as patrons, sorted, and `patronIds` those people's ids. `grade`
 *  is the grade in force on the sheet's today when loaded and `grades` every grade recorded. */
export type Person = {
  id: string;
  name: string;
  grade: string;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  holds: HoldFrom[];
  patrons: string[];
  patronIds: string[];
  grades: GradeFrom[];
  /** The person's own terms in days; "" for none. */
  terms: string;
};

/** A hold from a date to a date, both included (YYYY-MM-DD; to "" when open-ended). */
export type HoldFrom = { from: string; to: string };

/** Whether one of the person's holds covers the date. */
/** Whether the person's retirement date is reached on the sheet's today: from then their OPEN and
 *  PENDING claims, unless bound by a statement, count in no live total. */
export const retiredOn = (person: Person, today: string | undefined) =>
  person.retiredFrom !== '' && today !== undefined && today >= person.retiredFrom;

export const heldOn = (person: Person, date: string) =>
  person.holds.some((h) => h.from <= date && (h.to === '' || date <= h.to));

/** A grade in force from a date (YYYY-MM-DD; "" for the beginning of time). */
export type GradeFrom = { from: string; grade: string };

/** The person's grade in force on a date: the one with the latest from-date on or before it (with
 *  no date yet, the one in force on the sheet's today as loaded). */
export function gradeOn(person: Person, date: string | undefined): string {
  if (date === undefined) return person.grade;
  let found: GradeFrom | undefined;
  for (const g of person.grades) {
    if (g.from <= date && (found === undefined || g.from >= found.from)) found = g;
  }
  return found?.grade ?? person.grade;
}

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople(sheet: string): Person[] {
  const { data } = useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: sheet !== '',
  });
  return data ?? [];
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim; `amount` is shown with two decimals ("10.25"); `number` is the one given when it was
 *  opened (a voided claim keeps it), "" for a draft; `due` is the due fixed when it was settled, else the
 *  figure the person's last statement bound it to, "" while its due is live (worked from the current
 *  rate) or bound to n/a (a PENDING claim is never bound: its due is live); `stated` is whether the last statement bound it. A claim with a negative
 *  amount is a correction: its due has no floor and no late charge. */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  /** The user who opened the claim, "" if it was never opened. */
  openedBy: string;
  stated: boolean;
  /** The number of the SETTLED claim a correction (a negative amount) corrects, "" for any other claim. */
  corrects: string;
  /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects. */
  roundingDate: string;
  /** The claim's due-by, fixed when it was created: its date plus the first of its person's own terms, their grade's terms and the sheet's terms in force on that date. */
  dueBy: string;
  /** The claim's status log, oldest first: "<STATUS> by <user> on <date> due=<due>" per status it has had. */
  log: string[];
  /** The date the claim was last deferred until, "" if it was never deferred. */
  deferredUntil: string;
  /** The claim's proofs count. */
  proofs: string;
  /** The number of the claim a split made this claim from, "" for any other claim. */
  splitFrom: string;
  /** The user whose open editor locks the claim for everyone else, "" when unlocked. */
  lockedBy?: string;
  /** Whether the claim was added while its period was soft-closed. */
  lateEntry?: boolean;
};

/** OPEN and PENDING claims are open: their due is live (unless bound), they go overdue and a hold
 *  takes them out of the totals. */
export const isOpen = (c: { status?: string }) => c.status === 'OPEN' || c.status === 'PENDING';

/** Only OPEN, PENDING and SETTLED claims count toward claimed, due-total and every total. */
export const counts = (c: Claim) => isOpen(c) || c.status === 'SETTLED';

/** Whether a statement binds the claim's figure now: a PENDING claim is never bound. */
export const isBound = (c: Claim) => c.stated && c.status !== 'PENDING';

/** Whether a claim is deferred on the sheet's today: OPEN and deferred until a later date. A deferred claim
 *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
export const isDeferred = (c: { status?: string; deferredUntil?: string }, today: string | undefined) =>
  c.status === 'OPEN' && !!c.deferredUntil && today !== undefined && today < c.deferredUntil;

/** Whether a claim counts in the live totals: it counts, is not deferred on the sheet's today, and is not
 *  open, unbound and dated within one of its person's holds (`heldOn`). */
export const countsLive = (c: Claim, heldOn: (date: string) => boolean, today: string | undefined) =>
  counts(c) && !isDeferred(c, today) && !(isOpen(c) && !isBound(c) && heldOn(c.date));

/** The status a claim had at the end of the day, as its status log records it (each line dated the sheet's today
 *  when the change was made); undefined when it was added after that day. */
export function statusAt(c: Claim, end: string): ClaimStatus | undefined {
  let at: ClaimStatus | undefined;
  for (const line of c.log ?? []) {
    const m = / on (\d{4}-\d{2}-\d{2}) due=[^ ]*$/.exec(line);
    if (m && m[1] <= end) at = line.slice(0, line.indexOf(' ')) as ClaimStatus;
  }
  return at;
}

/** Whether a claim counts in a period ending on `end`: by the status it had at the end of that day, and, as in the
 *  live totals, not deferred on the sheet's today and not open, unbound and dated within one of its person's holds. */
export const countsAtEnd = (c: Claim, end: string, heldOn: (date: string) => boolean, today: string | undefined) => {
  const then = statusAt(c, end);
  return then !== undefined && counts({ ...c, status: then }) && !isDeferred(c, today) && !(isOpen(c) && !isBound(c) && heldOn(c.date));
};

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** The sheet's claims, newest first. */
export function useClaims(sheet: string): Claim[] {
  const { data } = useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The amounts of the claims that count added up, shown with two decimals. Summed in whole cents
 *  so no float drift shows. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade's rate: a percent shown with two decimals ("12.50"), in force from a date (YYYY-MM-DD;
 *  "" for from the beginning of time) through a date ("" for no end). */
export type Rate = { grade: string; rate: string; from: string; to: string };

export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'] as const;

/** The sheet's rates, by grade then from-date (from the beginning of time first). */
export function useRates(sheet: string): Rate[] {
  const { data } = useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The grade's rate in force on a date: the one with the latest from-date on or before it;
 *  undefined when none applies, when that one's to-date is before the date (or the date is not known yet). */
export function rateOn(rates: Rate[], grade: string, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade === grade && r.from <= date && (found === undefined || r.from >= found.from)) found = r;
  }
  if (found === undefined || (found.to !== '' && found.to < date)) return undefined;
  return found.rate;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A period: a name unique on the sheet, from and to dates (YYYY-MM-DD, both inclusive), whether it
 *  is closed, the due-total fixed when it was closed ("" while open), and each person's due-total for
 *  it fixed then, by person id (empty while open; a person added later has none). A soft-closed period
 *  has its figures fixed the same way, but its claims stay open to change. */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string;
  closedPersonTotals: Record<string, string>;
  softClosed: boolean;
};

export const periodsKey = (sheet: string) => ['sheet', sheet, 'periods'] as const;

/** The sheet's periods, by from-date. */
export function usePeriods(sheet: string): Period[] {
  const { data } = useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The period whose dates contain a date; periods never overlap, so there is at most one. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useSheetToday } from '../sheet/useSheetToday';

/** A role a user name holds on the sheet: clerk (any name not listed), steward or viewer (sees everything, changes nothing). */
export type Role = { user: string; role: string };

/** The sheet's settings, each dated one as in force on the sheet's today: the clerk limit with two decimals ("" for no limit), the floor with two
 *  decimals (a claim's live due is at least it), the terms in days (a new claim's due-by is its date
 *  plus them, unless its person's grade has its own terms), the late percent with two decimals (an overdue claim gains it of its figure for every
 *  full 30 days overdue), the policy date ("" for blank: the sheet's today), the period numbering from ("" for off: from it,
 *  a claim opened is numbered within its period), the roles set and each grade's own terms in days, by grade
 *  (a grade not listed uses the sheet's terms), the cap with two decimals ("" for none: a person's due-total is at most it) and the
 *  proof threshold with two decimals ("" for none: above the one in force on its date a claim needs a proof to be settled or approved)
 *  and each action's permission, by action: the roles that may take it, comma separated ("" for the standing rule),
 *  and every delegation of the steward role, in the order given. */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string; roles: Role[]; gradeTerms: Record<string, string>; cap: string; dated: Record<string, Dated[]>; proofThreshold: string; perms: Record<string, string>; graceDays: string; delegations: Delegation[] };

/** A steward's delegation of the steward role: while the sheet's today is from..to (inclusive) the user acts as a
 *  steward, and the audit lines of their changes end with for=<by>. */
export type Delegation = { user: string; from: string; to: string; by: string };

/** A value recorded for a dated setting (clerk-limit, floor, terms, terms-<grade>, late-pct, cap): the date
