  closedTotal: string;
  closedPersonTotals: Record<string, string>;
  softClosed: boolean;
};

export const periodsKey = (sheet: string) => ['sheet', sheet, 'periods'] as const;

/** The sheet's periods, by from-date. */
export function usePeriods(sheet: string): Period[] {
  const { data } = useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The period whose dates contain a date; periods never overlap, so there is at most one. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useSheetToday } from '../sheet/useSheetToday';

/** A role a user name holds on the sheet: clerk (any name not listed), steward or viewer (sees everything, changes nothing). */
export type Role = { user: string; role: string };

/** The sheet's settings, each dated one as in force on the sheet's today: the clerk limit with two decimals ("" for no limit), the floor with two
 *  decimals (a claim's live due is at least it), the terms in days (a new claim's due-by is its date
 *  plus them, unless its person's grade has its own terms), the late percent with two decimals (an overdue claim gains it of its figure for every
 *  full 30 days overdue), the policy date ("" for blank: the sheet's today), the period numbering from ("" for off: from it,
 *  a claim opened is numbered within its period), the roles set and each grade's own terms in days, by grade
 *  (a grade not listed uses the sheet's terms), the cap with two decimals ("" for none: a person's due-total is at most it) and the
 *  proof threshold with two decimals ("" for none: above the one in force on its date a claim needs a proof to be settled or approved)
 *  and each action's permission, by action: the roles that may take it, comma separated ("" for the standing rule),
 *  and every delegation of the steward role, in the order given. */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string; roles: Role[]; gradeTerms: Record<string, string>; cap: string; dated: Record<string, Dated[]>; proofThreshold: string; perms: Record<string, string>; graceDays: string; delegations: Delegation[] };

/** A steward's delegation of the steward role: while the sheet's today is from..to (inclusive) the user acts as a
 *  steward, and the audit lines of their changes end with for=<by>. */
export type Delegation = { user: string; from: string; to: string; by: string };

/** A value recorded for a dated setting (clerk-limit, floor, terms, terms-<grade>, late-pct, cap): the date
 *  it is in force from and the value ("" for none). The figures shown in Settings are those in force on the
 *  sheet's today; these are every value recorded, oldest first. */
export type Dated = { from: string; value: string };

/** The value of a dated setting in force on a date: the one with the latest from-date on or before it,
 *  else the sheet's starting value. */
export function inForce(settings: Settings | undefined, key: string, date: string, start: string): string {
  const before = (settings?.dated?.[key] ?? []).filter((d) => d.from <= date);
  const found = before[before.length - 1];
  return found === undefined || found.value === '' ? start : found.value;
}

/** The floor a sheet starts with, used until its settings have loaded. */
export const DEFAULT_FLOOR = '1.00';

/** The actions the permission matrix covers; a blank entry keeps the standing rule: open, settle, void and close
 *  by clerk and steward, reassign and reopen by steward. */
export const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;

export const settingsKey = (sheet: string) => ['sheet', sheet, 'settings'] as const;

export function useSettings(sheet: string): Settings | undefined {
  const { data } = useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    enabled: sheet !== '',
  });
  return data;
}

/** The sheet's floor in force on a date (a claim's: its date). */
export function useFloor(sheet: string): (date: string) => string {
  const settings = useSettings(sheet);
  return (date) => inForce(settings, 'floor', date, DEFAULT_FLOOR);
}

/** The late percent a sheet starts with, used until its settings have loaded. */
export const DEFAULT_LATE_PCT = '0.00';

/** The sheet's late percent in force on a date (a late charge's: each 30-day boundary of an overdue claim). */
export function useLatePct(sheet: string): (date: string) => string {
  const settings = useSettings(sheet);
  return (date) => inForce(settings, 'late-pct', date, DEFAULT_LATE_PCT);
}

/** The sheet's policy date: the one set, or the sheet's today when it is blank. A claim dated before
 *  it rounds half up, one on or after it half to even. Undefined while loading. */
export function usePolicyDate(sheet: string): string | undefined {
  const set = useSettings(sheet)?.policyDate;
  const today = useSheetToday(sheet);
  return set ? set : today;
}

/** The sheet's cap in force on its today ("" for none): a person's due-total is at most it. */
export function useCap(sheet: string): string {
  return useSettings(sheet)?.cap ?? '';
}
import { countsLive, isOpen, useClaims } from '../claims/useClaims';
import { isOverdue } from '../claims/overdue';
import { capped, claimDue, dueTotal, excess, formatCents, toCents } from '../rates/due';
import { rateOn, useRates } from '../rates/useRates';
import { useCap, useFloor, useLatePct, usePolicyDate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheetToday';
import { gradeOn, heldOn, retiredOn, usePeople, type Person } from './usePeople';

export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

// The figures the people list, its totals, the summary and the header are all worked from, so
// every place that repeats a figure shows the same one.
export function useSheetFigures(sheet: string) {
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const late = { pct: useLatePct(sheet), today };
  const policy = usePolicyDate(sheet);
  const cap = useCap(sheet);
  const byId = new Map(people.map((p) => [p.id, p]));
  const live = claims.filter((c) => {
    const person = byId.get(c.personId);
    return person !== undefined && countsLive(c, (date) => heldOn(person, date) || retiredOn(person, today), today);
  });
  // A claim is worked at the grade in force on its date; the row shows the one in force today.
  // The sum of a person's figures, before the cap.
  const uncappedOf = (person: Person) =>
    dueTotal(
      live.filter((c) => c.personId === person.id),
      (date) => rateOn(rates, gradeOn(person, date), date),
      rateOn(rates, gradeOn(person, today), today),
      floor,
      late,
      policy,
    );
  // A person's due-total: at most the sheet's cap (n/a is not capped); everything that adds up
  // due-totals uses it. Their excess is how far the sum of their figures is above the cap.
  const totalOf = (person: Person) => capped(uncappedOf(person), cap);
  const excessOf = (person: Person) => excess(uncappedOf(person), cap);
  const overdue = live.filter((c) => isOverdue(c, today));
  const overdueSum = (cs: typeof overdue) =>
    cs.reduce((sum, c) => sum + (claimDue(c, rateOn(rates, gradeOn(byId.get(c.personId)!, c.date), c.date), floor, late, policy) ?? 0n), 0n);
  const overdueTotal = (cs: typeof overdue) => formatCents(overdueSum(cs));
  // The sheet's due-total: the people's due-totals added up, skipping n/a, trimmed.
  const sheetDueTotal = formatCents(trimmedSum(people.map(totalOf).filter((due): due is bigint => due !== null)));
  // The sheet's overdue-total: each person's overdue-total (always a figure) added up, trimmed.
  const sheetOverdueTotal = formatCents(trimmedSum(people.map((p) => overdueSum(overdue.filter((c) => c.personId === p.id)))));
  // Active: an OPEN or PENDING claim that counts, dated within the 30 days up to and including today.
  const activeFrom = today === undefined ? undefined : daysBefore(today, 29);
  const isActive = (person: Person) =>
    activeFrom !== undefined &&
    live.some((c) => c.personId === person.id && isOpen(c) && c.date >= activeFrom && c.date <= today!);
  // Settled: the sum of a person's SETTLED claims' frozen figures, dated within the 90 days up to and including today.
  const settledFrom = today === undefined ? undefined : daysBefore(today, 89);
  const recentSettledOf = (person: Person) =>
    settledFrom === undefined
      ? 0n
      : claims
          .filter((c) => c.personId === person.id && c.status === 'SETTLED' && c.date >= settledFrom && c.date <= today! && /^-?\d+\.\d{2}$/.test(c.due))
          .reduce((sum, c) => sum + toCents(c.due), 0n);
  const onSheet = new Set(people.map((p) => p.id));
  const sheetClaims = claims.filter((c) => onSheet.has(c.personId));
  const statusCount = (s: (typeof STATUSES)[number]) => sheetClaims.filter((c) => c.status === s).length;
  return { people, claims, rates, today, byId, live, totalOf, excessOf, overdue, overdueTotal, sheetDueTotal, sheetOverdueTotal, statusCount, isActive, recentSettledOf };
}

// People's figures added up, leaving out the single highest and the single lowest when there are
// three or more.
function trimmedSum(figures: bigint[]): bigint {
  const sum = figures.reduce((a, b) => a + b, 0n);
  if (figures.length < 3) return sum;
  const max = figures.reduce((a, b) => (b > a ? b : a));
  const min = figures.reduce((a, b) => (b < a ? b : a));
  return sum - max - min;
}

// The ISO date `days` days before `date`.
function daysBefore(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - days);
  return d.toISOString().slice(0, 10);
}
import { countsAtEnd, useClaims } from '../claims/useClaims';
import { gradeOn, heldOn, usePeople } from '../people/usePeople';
import { claimDue, toCents } from '../rates/due';
import { rateOn, useRates } from '../rates/useRates';
import { useFloor, useLatePct, usePolicyDate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheetToday';
import { periodOf, usePeriods, type Period } from './usePeriods';

/** A person's due-total for a period: the dues as shown now, late charges included, of their claims whose date
 *  falls in it that counted at the end of its last day (see countsAtEnd), leaving out their unbound OPEN claims dated within one of their holds (a claim whose due is n/a
 *  adds nothing); a closed or soft-closed period gives the figure fixed when it was closed (0.00 for a person added later). */
export function usePersonPeriodDueTotal(sheet: string): (period: Period, personId: string) => bigint {
  const periods = usePeriods(sheet);
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const floor = useFloor(sheet);
  const late = { pct: useLatePct(sheet), today: useSheetToday(sheet) };
  const policy = usePolicyDate(sheet);
  const personOf = new Map(people.map((p) => [p.id, p]));
  return (period: Period, personId: string) => {
    if (period.closed || period.softClosed) return toCents(period.closedPersonTotals[personId] ?? '0.00');
    const person = personOf.get(personId);
    if (!person) return 0n;
    return claims
      .filter((c) => c.personId === personId && countsAtEnd(c, period.to, (date) => heldOn(person, date), late.today) && periodOf(periods, c.date)?.name === period.name)
      .reduce((sum, c) => sum + (claimDue(c, rateOn(rates, gradeOn(person, c.date), c.date), floor, late, policy) ?? 0n), 0n);
  };
}

/** A period's due-total: the sum of every person's due-total for it. */
export function usePeriodDueTotal(sheet: string): (period: Period) => bigint {
  const people = usePeople(sheet);
  const personDueTotal = usePersonPeriodDueTotal(sheet);
  return (period: Period) => people.reduce((sum, p) => sum + personDueTotal(period, p.id), 0n);
}

